// The browser crypto module against the NORMATIVE vectors (canopy-web#1550):
// docs/vault/zk-v1/zk_v1_vectors.json, generated by zk_v1_reference.py. Every
// output must match BYTE FOR BYTE; the fixed ephemeral keys, nonces and salts
// are injected through the test-only `opts` parameters.
import { describe, expect, it } from 'vitest'
import raw from '../../../docs/vault/zk-v1/zk_v1_vectors.json?raw'
import {
  b64u,
  bytesToHex,
  decryptValue,
  deviceInfo,
  encryptValue,
  generateKeyPair,
  hexToBytes,
  importPrivateScalar,
  jkt,
  memberInfo,
  openUserKey,
  openUserKey2skd,
  parseSecretKeyCode,
  passphraseProblem,
  sealUserKey2skd,
  secretKeyCode,
  parseRecoveryCode,
  prfInput,
  publicJwk,
  recoveryCode,
  sealUserKey,
  unwrapEcdhEs,
  unwrapRecovery,
  wrapEcdhEs,
  wrapRecovery,
  type Ephemeral,
} from './zk'

const V = JSON.parse(raw) as {
  inputs: Record<string, string> & {
    kv: number
    device_pub_jwk: { x: string; y: string }
    user_pub_jwk: { x: string; y: string }
  }
  outputs: Record<string, never> & {
    value: string
    device_wrap: { alg: 'ecdh-es'; epk: string; n: string; ct: string }
    member_wrap: { alg: 'ecdh-es'; epk: string; n: string; ct: string }
    device_wrap_shared_secret_hex: string
    prf_input_b64u: string
    user_key_seal: { alg: 'prf'; cred: string; s: string; n: string; ct: string }
    recovery_wrap: { alg: 'recovery'; s: string; n: string; ct: string }
    recovery_code: string
    user_key_seal_2skd: { alg: '2skd'; kdf: 'pbkdf2-sha256'; i: number; s: string; n: string; ct: string }
    secret_key_code: string
  }
}
const I = V.inputs
const O = V.outputs
const vk = hexToBytes(I.vk_hex)
const nonce = hexToBytes(I.nonce_hex)
const salt = hexToBytes(I.salt_hex)

/** TEST ONLY: a scalar's public half, by importing it as a PKCS#8 key without
 *  one (WebCrypto derives it). Production always has the public JWK. */
async function keyFromScalar(hex: string): Promise<Ephemeral> {
  const prefix = hexToBytes('308141020100301306072a8648ce3d020106082a8648ce3d030107042730250201010420')
  const der = new Uint8Array(prefix.length + 32)
  der.set(prefix)
  der.set(hexToBytes(hex), prefix.length)
  const k = await crypto.subtle.importKey('pkcs8', der, { name: 'ECDH', namedCurve: 'P-256' }, true, ['deriveBits'])
  const pub = publicJwk(await crypto.subtle.exportKey('jwk', k))
  // …and back through the production path: importKey from the scalar via JWK `d`.
  return { privateKey: await importPrivateScalar(hexToBytes(hex), pub), publicJwk: pub }
}

describe('zk v1 vectors', () => {
  it('value: zk1 AES-GCM bound to agent, name and kv', async () => {
    const got = await encryptValue(vk, I.agent_id, I.value_name, I.kv, I.value_plaintext, { nonce })
    expect(got).toBe(O.value)
    expect(await decryptValue(vk, I.agent_id, I.value_name, I.kv, O.value)).toBe(I.value_plaintext)
    await expect(decryptValue(vk, '43', I.value_name, I.kv, O.value)).rejects.toThrow()
    await expect(decryptValue(vk, I.agent_id, 'other-name', I.kv, O.value)).rejects.toThrow()
    await expect(decryptValue(vk, I.agent_id, I.value_name, 2, O.value)).rejects.toThrow()
  })

  it('device keys: public half and RFC 7638 thumbprint', async () => {
    const device = await keyFromScalar(I.device_priv_scalar_hex)
    expect(device.publicJwk).toEqual({ kty: 'EC', crv: 'P-256', ...I.device_pub_jwk })
    expect(await jkt(device.publicJwk)).toBe(I.device_jkt)
    const user = await keyFromScalar(I.user_priv_scalar_hex)
    expect(user.publicJwk).toEqual({ kty: 'EC', crv: 'P-256', ...I.user_pub_jwk })
  })

  it('device wrap: ECDH-ES byte for byte, and the device unwraps it', async () => {
    const e1 = await keyFromScalar(I.ephemeral_device_wrap_scalar_hex)
    const info = deviceInfo(I.agent_id, I.kv, I.device_jkt)
    const wrap = await wrapEcdhEs(vk, I.device_pub_jwk, info, { ephemeral: e1, nonce })
    expect(wrap).toEqual(O.device_wrap)
    const device = await keyFromScalar(I.device_priv_scalar_hex)
    expect(bytesToHex(await unwrapEcdhEs(O.device_wrap, device.privateKey, device.publicJwk, info))).toBe(I.vk_hex)
    // Z is what a hardware key hands back (ecdh-derive): the same shared secret.
    const z = await crypto.subtle.deriveBits(
      { name: 'ECDH', public: await crypto.subtle.importKey('jwk', e1.publicJwk, { name: 'ECDH', namedCurve: 'P-256' }, true, []) },
      device.privateKey, 256)
    expect(bytesToHex(new Uint8Array(z))).toBe(O.device_wrap_shared_secret_hex)
    await expect(unwrapEcdhEs(O.device_wrap, device.privateKey, device.publicJwk,
      deviceInfo(I.agent_id, 2, I.device_jkt))).rejects.toThrow()
  })

  it('member wrap: ECDH-ES to the person, opened through their sealed key', async () => {
    const e2 = await keyFromScalar(I.ephemeral_member_wrap_scalar_hex)
    const info = memberInfo(I.agent_id, I.kv, I.user_id)
    expect(await wrapEcdhEs(vk, I.user_pub_jwk, info, { ephemeral: e2, nonce })).toEqual(O.member_wrap)
    // The person path end to end: PRF output → open the seal → scalar → unwrap.
    const scalar = await openUserKey(O.user_key_seal, I.user_id, hexToBytes(I.prf_output_hex))
    expect(bytesToHex(scalar)).toBe(I.user_priv_scalar_hex)
    const priv = await importPrivateScalar(scalar, I.user_pub_jwk)
    expect(bytesToHex(await unwrapEcdhEs(O.member_wrap, priv, I.user_pub_jwk, info))).toBe(I.vk_hex)
    await expect(unwrapEcdhEs(O.member_wrap, priv, I.user_pub_jwk, memberInfo(I.agent_id, I.kv, '8'))).rejects.toThrow()
  })

  it('user keyset seal and the PRF input', async () => {
    expect(b64u(await prfInput(I.user_id))).toBe(O.prf_input_b64u)
    const seal = await sealUserKey(hexToBytes(I.user_priv_scalar_hex), I.user_id, I.credential_id_b64u,
      hexToBytes(I.prf_output_hex), { salt, nonce })
    expect(seal).toEqual(O.user_key_seal)
    await expect(openUserKey(O.user_key_seal, '8', hexToBytes(I.prf_output_hex))).rejects.toThrow()
  })

  it('recovery wrap and the Crockford code', async () => {
    const r = hexToBytes(I.recovery_secret_hex)
    expect(await wrapRecovery(vk, I.agent_id, I.kv, r, { salt, nonce })).toEqual(O.recovery_wrap)
    expect(recoveryCode(r)).toBe(O.recovery_code)
    expect(bytesToHex(parseRecoveryCode(O.recovery_code))).toBe(I.recovery_secret_hex)
    // Typed sloppily: lower case, spaces, O for 0 and l for 1.
    const sloppy = O.recovery_code.toLowerCase().replace(/-/g, ' ').replace(/0/g, 'o').replace(/1/g, 'l')
    expect(bytesToHex(parseRecoveryCode(sloppy))).toBe(I.recovery_secret_hex)
    expect(bytesToHex(await unwrapRecovery(O.recovery_wrap, I.agent_id, I.kv, parseRecoveryCode(O.recovery_code))))
      .toBe(I.vk_hex)
    expect(() => parseRecoveryCode('ABCD-EFGH')).toThrow()
  })

  it('passphrase + Secret Key seal (2SKD), NFKC-normalized', async () => {
    const sk = hexToBytes(I.secret_key_hex)
    const seal = await sealUserKey2skd(hexToBytes(I.user_priv_scalar_hex), I.user_id, I.passphrase, sk, { salt, nonce })
    expect(seal).toEqual(O.user_key_seal_2skd)
    expect(secretKeyCode(sk)).toBe(O.secret_key_code)
    expect(bytesToHex(parseSecretKeyCode(O.secret_key_code))).toBe(I.secret_key_hex)
    expect(bytesToHex(parseSecretKeyCode(O.secret_key_code.toLowerCase().replace(/-/g, ' ')))).toBe(I.secret_key_hex)
    // "\ufb01" (the fi ligature) normalizes to "fi".
    const opened = await openUserKey2skd(O.user_key_seal_2skd, I.user_id, 'correct horse battery staple fi', sk)
    expect(bytesToHex(opened)).toBe(I.user_priv_scalar_hex)
    await expect(openUserKey2skd(O.user_key_seal_2skd, I.user_id, 'wrong passphrase', sk)).rejects.toThrow()
    await expect(openUserKey2skd(O.user_key_seal_2skd, I.user_id, I.passphrase, new Uint8Array(16))).rejects.toThrow()
    await expect(openUserKey2skd(O.user_key_seal_2skd, '8', I.passphrase, sk)).rejects.toThrow()
  })

  it('passphrase strength floor', () => {
    expect(passphraseProblem('short')).not.toBeNull()
    expect(passphraseProblem('aaaaaaaaaaaaaaaa')).not.toBeNull()
    expect(passphraseProblem('correct horse battery')).toBeNull()
  })

  it('fresh randomness round-trips (the production path)', async () => {
    const me = await generateKeyPair()
    const info = memberInfo('9', 3, '5')
    const wrap = await wrapEcdhEs(vk, me.publicJwk, info)
    expect(bytesToHex(await unwrapEcdhEs(wrap, me.privateKey, me.publicJwk, info))).toBe(I.vk_hex)
    expect(me.scalar.length).toBe(32)
  })
})
